// Gabarit Accueil, reponse : une conversation = un travail, quel que soit le nombre de canaux (p6:280-285).
const cfg = $('Lire les réglages').first().json || {};
const org = $('Compte de cette copie').first().json.organisation_id;
if (cfg.interrupteur_general === false || cfg.interrupteur_departement === false) return [];
const simulation = cfg.simulation !== false;
const deja = new Set(cfg.cles_existantes || []);
const arobase = String.fromCharCode(64);
const masquer = (t) => String(t || '').split(String.fromCharCode(10)).join(' ').split(' ').map((w) => (w.indexOf(arobase) >= 0 ? '[adresse]' : w.split('').filter((c) => c >= '0' && c <= '9').length >= 8 ? '[numéro]' : w)).join(' ').slice(0, 4000);
const groupes = new Map();
for (const it of $input.all()) {
  const ev = it.json;
  const d = ev.demande;
  if (!d || deja.has(ev.cle)) continue;
  const g = groupes.get(ev.conversation_cle);
  if (!g) groupes.set(ev.conversation_cle, { ev: ev, canaux: [ev.canal_origine], ids: [ev.id] });
  else {
    g.ids.push(ev.id);
    if (g.canaux.indexOf(ev.canal_origine) < 0) g.canaux.push(ev.canal_origine);
    if (Date.parse(d.recu_le) >= Date.parse(g.ev.demande.recu_le)) g.ev = ev;
  }
}
return [...groupes.entries()].map(([conv, g]) => ({ json: { organisation_id: org, simulation: simulation, config: cfg, conversation_cle: conv, canal_origine: g.ev.canal_origine, canaux: g.canaux, evenement_ids: g.ids, id_boite: g.ev.id_boite || '', fil_externe: g.ev.fil_externe || '', photo_url: (g.ev.donnees && g.ev.donnees.photo_url) || '', demande: g.ev.demande, message_masque: masquer(g.ev.demande.message) } }));

// La photo se decrit, elle ne se chiffre pas : un chiffre ou un prix dans la description la fait refuser.
const g = $('Regrouper par conversation').item.json;
const brut = $input.first().json;
const d = String(brut.content || brut.text || (brut.output && brut.output.text) || '').slice(0, 400);
const chiffre = d.split('').some((c) => c >= '0' && c <= '9') || d.indexOf('€') >= 0 || d.toLowerCase().indexOf('euro') >= 0;
return [{ json: Object.assign({}, g, { photo_description: chiffre ? '' : d, photo_refusee: chiffre }) }];

